const config = $input.first().json.config || {};
const all = config.accelerators || [];
// Only 'json'-method accelerators are buildable right now -- 'html' ones need
// per-site scraping logic that hasn't been written or verified yet, and are
// deliberately left disabled in accelerators.json until that happens.
const enabled = all.filter(a => a.enabled === true && a.method === 'json');
return enabled.map(a => ({ json: { accel_id: a.id, accel_name: a.name, url: a.url, fields: a.fields } }));

const results = [];
const accelItems = $('Filter Enabled JSON Accelerators').all();
const fetchItems = $input.all();

for (let i = 0; i < fetchItems.length; i++) {
  const accel = accelItems[i].json;
  const resp = fetchItems[i].json;
  if (resp.statusCode !== 200) continue;

  let list;
  try {
    const raw = resp.body !== undefined ? resp.body : resp.data;
    list = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    continue;
  }
  if (!Array.isArray(list)) continue;

  const f = accel.fields || { name: 'name', domain: 'website' };
  for (const c of list) {
    const regions = c.regions || [];
    const locationText = (c.all_locations || '').toLowerCase();
    const isIndia = regions.includes('India') || locationText.includes('india');
    const isHiring = c.isHiring === true;
    const isActive = c.status === 'Active';
    const website = c[f.domain];
    if (isIndia && isHiring && isActive && website) {
      results.push({
        json: {
          accelerator: accel.accel_id,
          company: c[f.name],
          slug: c.slug || null,
          website
        }
      });
    }
  }
}

return results;

// A board's real token is rarely just the company's slug (e.g. Razorpay's
// real Greenhouse token is 'razorpaysoftwareprivatelimited', not 'razorpay')
// -- guessing tokens directly was tried and empirically produced 0 hits
// across 49 real companies. What works: the company's own careers/jobs page
// almost always links its real ATS board directly, so extract the token
// from that link instead of guessing it.
//
// Avoid the URL constructor here -- n8n's Code node sandbox doesn't expose
// it, so new URL(...) throws ReferenceError for every item and a try/catch
// around it silently swallows the whole batch with zero visible error.
function getOrigin(raw) {
  const m = (raw || '').match(/^https?:\/\/[^\/]+/i);
  return m ? m[0] : null;
}

const PATHS = ['/careers', '/jobs', ''];
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const domain = getOrigin(j.website);
  if (!domain) continue;
  for (const path of PATHS) {
    out.push({
      json: {
        accelerator: j.accelerator,
        company: j.company,
        slug: j.slug,
        website: j.website,
        candidate_url: domain + path
      }
    });
  }
}

return out;

const ATS_PATTERNS = [
  { provider: 'greenhouse',      re: /(?:job-boards|boards)\.greenhouse\.io\/([a-zA-Z0-9_-]+)/ },
  { provider: 'lever',           re: /jobs\.lever\.co\/([a-zA-Z0-9_-]+)/ },
  { provider: 'ashby',           re: /jobs\.ashbyhq\.com\/([a-zA-Z0-9_-]+)/ },
  { provider: 'workable',        re: /apply\.workable\.com\/([a-zA-Z0-9_-]+)/ },
  { provider: 'smartrecruiters', re: /jobs\.smartrecruiters\.com\/([a-zA-Z0-9_-]+)/ },
  { provider: 'recruitee',       re: /([a-zA-Z0-9_-]+)\.recruitee\.com/ }
];

const candidateItems = $('Build Career Page Candidates').all();
const fetchItems = $input.all();

// Group candidate page results by company (accelerator+slug), keep the
// first candidate URL that yields a real ATS link.
const byCompany = new Map();
for (let i = 0; i < fetchItems.length; i++) {
  const cand = candidateItems[i].json;
  const key = cand.accelerator + ':' + cand.slug;
  if (byCompany.has(key) && byCompany.get(key).found) continue;

  const resp = fetchItems[i].json;
  const body = (resp.statusCode === 200) ? (typeof resp.body === 'string' ? resp.body : (typeof resp.data === 'string' ? resp.data : '')) : '';

  let match = null;
  for (const p of ATS_PATTERNS) {
    const m = body.match(p.re);
    if (m) { match = { provider: p.provider, token: m[1] }; break; }
  }

  if (match) {
    byCompany.set(key, {
      found: true,
      accelerator: cand.accelerator,
      company: cand.company,
      slug: cand.slug,
      website: cand.website,
      provider: match.provider,
      token: match.token,
      source_page: cand.candidate_url
    });
  } else if (!byCompany.has(key)) {
    byCompany.set(key, { found: false, accelerator: cand.accelerator, company: cand.company, slug: cand.slug, website: cand.website });
  }
}

return Array.from(byCompany.values()).filter(v => v.found).map(v => ({ json: v }));

const PATTERNS = {
  greenhouse:      'https://boards-api.greenhouse.io/v1/boards/{token}/jobs',
  lever:           'https://api.lever.co/v0/postings/{token}?mode=json',
  ashby:           'https://api.ashbyhq.com/posting-api/job-board/{token}',
  workable:        'https://apply.workable.com/api/v1/widget/accounts/{token}',
  smartrecruiters: 'https://api.smartrecruiters.com/v1/companies/{token}/postings',
  recruitee:       'https://{token}.recruitee.com/api/offers/'
};

return $input.all().map(item => {
  const j = item.json;
  const pattern = PATTERNS[j.provider];
  return { json: { ...j, probe_url: pattern ? pattern.replace('{token}', j.token) : null } };
});

const linkItems = $('Probe Confirmed Token').all();
const confirmItems = $input.all();

return confirmItems.map((item, i) => {
  const j = linkItems[i].json;
  const resp = item.json;
  const confirmed = resp.statusCode === 200;
  return {
    json: {
      id: j.accelerator + ':' + j.slug,
      accelerator: j.accelerator,
      company: j.company,
      domain: j.website,
      confirmed,
      probe_result: JSON.stringify({ provider: j.provider, token: j.token, source_page: j.source_page, confirmed })
    }
  };
});

let candidates = 0;
try { candidates = $('Extract Candidate Companies').all().length; } catch (e) {}
const confirmed = $input.all().filter(i => i.json.confirmed === true).length;
const registered = $input.all().length;
return [{ json: { candidates, registered, confirmed } }];
